import random
from itertools import combinations

def girth_at_least_7(adj, n):
    # BFS from each node, check no cycle of length <= 6
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                if dist[u] >= 3:
                    continue
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nq.append(v)
                    elif v != parent[u]:
                        # found cycle of length dist[u]+dist[v]+1
                        if dist[u]+dist[v]+1 <= 6:
                            return False
            queue = nq
    return True

def has_short_cycle_adding(adj, u, v, n, max_len=6):
    # check if adding edge (u,v) creates cycle of length <= max_len
    # BFS from u avoiding direct edge, find distance to v
    from collections import deque
    dist = [-1]*n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_len-1:
            continue
        for y in adj[x]:
            if dist[y] == -1:
                dist[y] = dist[x]+1
                q.append(y)
    if dist[v] != -1 and dist[v] + 1 <= max_len:
        return True
    return False

def try_build(n=16, target=25, seed=0):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    pairs = list(combinations(range(n), 2))
    random.shuffle(pairs)
    for u,v in pairs:
        if has_short_cycle_adding(adj, u, v, n, 6):
            continue
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u,v))
        if len(edges) >= target+5:
            break
    return edges, adj

best = 0
best_edges = None
for seed in range(200):
    edges, adj = try_build(16, 30, seed)
    if len(edges) > best:
        best = len(edges)
        best_edges = edges
        print(seed, len(edges))
print("best:", best)
